      log('Checkout conversion successful', { sessionId: session.id });
      return { status: 'completed', paid: true };
    } else {
      log('Payment declined', { sessionId: session.id });
      return { status: 'declined', paid: false };
    }
  } catch (err) {
    log('Checkout error', { error: err.message });
